"""Tiny quiz-taking HTTP API.

Endpoints:
  POST /quizzes                create a quiz -> {"id": ...}
  GET  /quizzes/<id>/take?seed=N   shuffled questions (no answers) + mapping tokens
  POST /quizzes/<id>/attempts  grade responses -> {"score", "correct"}
"""
import base64
import json
import random
import uuid

from flask import Flask, jsonify, request

app = Flask(__name__)

# In-memory store: quiz_id -> {"title": str, "questions": [...]}
QUIZZES: dict[str, dict] = {}


class BadRequest(Exception):
    pass


def _err(message, status=400):
    return jsonify({"error": message}), status


def _require(cond, message):
    if not cond:
        raise BadRequest(message)


def parse_quiz_payload(data):
    """Validate and normalize a quiz-creation payload."""
    _require(isinstance(data, dict), "body must be a JSON object")
    _require(isinstance(data.get("title"), str), "'title' must be a string")
    questions = data.get("questions")
    _require(isinstance(questions, list) and len(questions) > 0,
             "'questions' must be a non-empty list")
    norm = []
    for i, q in enumerate(questions):
        _require(isinstance(q, dict), f"questions[{i}] must be an object")
        _require(isinstance(q.get("text"), str), f"questions[{i}].text must be a string")
        choices = q.get("choices")
        _require(isinstance(choices, list) and len(choices) == 4
                 and all(isinstance(c, str) for c in choices),
                 f"questions[{i}].choices must be a list of 4 strings")
        answer = q.get("answer")
        _require(isinstance(answer, int) and not isinstance(answer, bool)
                 and 0 <= answer <= 3,
                 f"questions[{i}].answer must be an integer in 0..3")
        norm.append({"text": q["text"], "choices": list(choices), "answer": answer})
    return {"title": data["title"], "questions": norm}


def permutation_for(quiz_id, seed, index):
    """Deterministic choice permutation for one question."""
    rng = random.Random(f"{quiz_id}:{seed}:{index}")
    perm = [0, 1, 2, 3]
    rng.shuffle(perm)
    return perm


def token_for(perm):
    """Opaque token encoding the shown->original choice mapping."""
    blob = json.dumps({"p": perm}, separators=(",", ":")).encode()
    return base64.urlsafe_b64encode(blob).decode().rstrip("=")


@app.errorhandler(BadRequest)
def handle_bad_request(e):
    return _err(str(e))


@app.post("/quizzes")
def create_quiz():
    data = request.get_json(silent=True)
    if data is None:
        return _err("request body must be valid JSON")
    quiz = parse_quiz_payload(data)
    quiz_id = uuid.uuid4().hex[:12]
    QUIZZES[quiz_id] = quiz
    return jsonify({"id": quiz_id}), 201


@app.get("/quizzes/<quiz_id>/take")
def take_quiz(quiz_id):
    quiz = QUIZZES.get(quiz_id)
    if quiz is None:
        return _err("quiz not found", 404)
    raw_seed = request.args.get("seed")
    try:
        seed = int(raw_seed)
    except (TypeError, ValueError):
        return _err("'seed' query parameter must be an integer")
    out = []
    for i, q in enumerate(quiz["questions"]):
        perm = permutation_for(quiz_id, seed, i)
        out.append({
            "text": q["text"],
            "choices": [q["choices"][j] for j in perm],
            "token": token_for(perm),
        })
    return jsonify({"id": quiz_id, "seed": seed, "title": quiz["title"],
                    "questions": out})


@app.post("/quizzes/<quiz_id>/attempts")
def submit_attempt(quiz_id):
    quiz = QUIZZES.get(quiz_id)
    if quiz is None:
        return _err("quiz not found", 404)
    data = request.get_json(silent=True)
    if data is None:
        return _err("request body must be valid JSON")
    _require(isinstance(data, dict), "body must be a JSON object")
    seed = data.get("seed")
    _require(isinstance(seed, int) and not isinstance(seed, bool),
             "'seed' must be an integer")
    responses = data.get("responses")
    _require(isinstance(responses, list) and len(responses) == len(quiz["questions"])
             and all(isinstance(r, int) and not isinstance(r, bool) and 0 <= r <= 3
                     for r in responses),
             "'responses' must be a list of choice indices matching the question count")
    correct = []
    for i, q in enumerate(quiz["questions"]):
        perm = permutation_for(quiz_id, seed, i)
        # The client answered with the choice as displayed at position `responses[i]`;
        # map it back to the original index via the deterministic permutation.
        chosen_original = perm[responses[i]]
        correct.append(chosen_original == q["answer"])
    score = sum(correct) / len(correct)
    return jsonify({"score": score, "correct": correct})


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000)

